const dsl = `workspace "Library" "A small public library system." {
    model {
        patron = person "Patron" "Borrows books at the library."
        library = softwareSystem "Library" "Manages books and loans." {
            catalog = container "Catalog Web App" "Lets patrons browse the catalogue." "Python"
            circulation = container "Circulation Service" "Records loans and returns." "Java"
        }
        patron -> catalog "Browses the catalogue through" "HTTPS"
        catalog -> circulation "Records loans via" "gRPC"
    }
    views {
        systemContext library "SystemContext" {
            include *
            autoLayout
        }
    }
}`;

const { definition } = await tools.structurizr["export-plantuml"]({ dsl, viewKey: "SystemContext" });

// --- UTF-8 encode ---
function utf8Bytes(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.codePointAt(i);
    if (c > 0xffff) i++;
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return new Uint8Array(out);
}

// --- DEFLATE with stored (uncompressed) blocks: valid deflate, no compression needed ---
function deflateStored(bytes) {
  const out = [];
  const push16 = (n) => { out.push(n & 0xff, (n >> 8) & 0xff); };
  let i = 0;
  const n = bytes.length;
  if (n === 0) { out.push(0x01); push16(0); push16(0xffff); return new Uint8Array(out); }
  while (i < n) {
    const len = Math.min(65535, n - i);
    const isFinal = (i + len >= n) ? 1 : 0;
    out.push(isFinal); // BFINAL bit set, BTYPE=00 (stored)
    push16(len);
    push16(~len & 0xffff);
    for (let j = 0; j < len; j++) out.push(bytes[i + j]);
    i += len;
  }
  return new Uint8Array(out);
}

// --- PlantUML custom base64 ---
const ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_";
function plantumlBase64(bytes) {
  let result = "";
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    const num = (b0 << 16) | (b1 << 8) | b2;
    result += ALPHABET[(num >> 18) & 63] + ALPHABET[(num >> 12) & 63] + ALPHABET[(num >> 6) & 63] + ALPHABET[num & 63];
  }
  const rem = bytes.length % 3;
  if (rem === 1) result = result.slice(0, -2);
  else if (rem === 2) result = result.slice(0, -1);
  return result;
}

const encoded = plantumlBase64(deflateStored(utf8Bytes(definition)));
return JSON.stringify({ encoded, length: encoded.length });

